import { defineMvuDataStore } from '@util/mvu';
import { applyCanonicalShenqiEffects, repairZeroShenqiSnapshot, SHENQI_EFFECTS, } from '../_shared/shenqiEffects';
import { 结算已学习功法属性 } from '../_shared/techniqueAttributeBonus';
import { Schema } from './schema';
import { clampVitalsToDerivedMax } from './vitals';
// 使用 -1（最新楼层）而非 getCurrentMessageId()，确保始终读取最新的变量数据，
// 不受状态栏 iframe 所在具体楼层的限制。加载旧存档时，将旧版复杂神契迁移为新版常驻效果。
export const VARIABLE_OPTION = { type: 'message', message_id: -1 };
function 同步当前在场到羁绊(data) {
    const 已同步 = [];
    for (const [name, present] of Object.entries(data.在场 ?? {})) {
        const bond = data.羁绊?.[name];
        if (!bond || _.isEqual(bond, present))
            continue;
        data.羁绊[name] = _.cloneDeep(present);
        已同步.push(name);
    }
    return 已同步;
}
function 截断主角气血法力(data) {
    const 当前值 = data.主角;
    const 截断值 = clampVitalsToDerivedMax(当前值);
    if (当前值.气血 === 截断值.气血 && 当前值.法力值 === 截断值.法力值)
        return false;
    当前值.气血 = 截断值.气血;
    当前值.法力值 = 截断值.法力值;
    return true;
}
function 修复全零神契快照(data) {
    const 已修复 = new Set();
    for (const name of Object.keys(SHENQI_EFFECTS)) {
        for (const roster of [data.在场, data.羁绊]) {
            const snapshot = roster?.[name];
            if (snapshot && repairZeroShenqiSnapshot(snapshot, name))
                已修复.add(name);
        }
    }
    return [...已修复];
}
export const useDataStore = defineMvuDataStore(Schema, VARIABLE_OPTION, data => {
    const 原始装备 = _.get(getVariables(VARIABLE_OPTION), 'stat_data.主角.装备', {});
    const 装备槽已补齐 = !_.isEqual(原始装备, data.value.主角.装备);
    const 神契已迁移 = applyCanonicalShenqiEffects(data.value);
    const 已结算功法 = 结算已学习功法属性(data.value);
    const 已同步人物 = 同步当前在场到羁绊(data.value);
    const 已修复全零神契 = 修复全零神契快照(data.value);
    const 主角气血法力已截断 = 截断主角气血法力(data.value);
    if (装备槽已补齐 ||
        神契已迁移 ||
        已结算功法.length > 0 ||
        已同步人物.length > 0 ||
        已修复全零神契.length > 0 ||
        主角气血法力已截断) {
        updateVariablesWith(variables => {
            if (装备槽已补齐) {
                _.set(variables, ['stat_data', '主角', '装备'], _.cloneDeep(data.value.主角.装备));
                console.info('[修仙状态栏] 已补齐固定装备槽位');
            }
            if (神契已迁移) {
                for (const [name, effect] of Object.entries(SHENQI_EFFECTS)) {
                    const god = data.value.古神列表[name];
                    if (!god)
                        continue;
                    _.set(variables, ['stat_data', '古神列表', name, '神契技能'], effect.技能);
                    _.set(variables, ['stat_data', '古神列表', name, '神契描述'], god.神契描述);
                }
            }
            if (已结算功法.length > 0) {
                _.set(variables, ['stat_data', '主角', '六维'], _.cloneDeep(data.value.主角.六维));
                _.set(variables, ['stat_data', '$flag', '已结算功法属性'], [...data.value.$flag.已结算功法属性]);
                _.set(variables, ['stat_data', '功法'], _.cloneDeep(data.value.功法));
                _.set(variables, ['stat_data', '初始功法'], _.cloneDeep(data.value.初始功法));
            }
            if (已同步人物.length > 0) {
                _.set(variables, ['stat_data', '羁绊'], _.cloneDeep(data.value.羁绊));
                console.info('[修仙状态栏] 已用在场实时快照校准同名羁绊人物', 已同步人物);
            }
            if (已修复全零神契.length > 0) {
                _.set(variables, ['stat_data', '在场'], _.cloneDeep(data.value.在场));
                _.set(variables, ['stat_data', '羁绊'], _.cloneDeep(data.value.羁绊));
                console.info('[修仙状态栏] 已修复旧版沙盒开场的全零神契六维', 已修复全零神契);
            }
            if (主角气血法力已截断) {
                _.set(variables, ['stat_data', '主角', '气血'], data.value.主角.气血);
                _.set(variables, ['stat_data', '主角', '法力值'], data.value.主角.法力值);
            }
            return variables;
        }, VARIABLE_OPTION);
    }
    watch(data, 当前数据 => {
        if (!截断主角气血法力(当前数据))
            return;
        updateVariablesWith(variables => {
            _.set(variables, ['stat_data', '主角', '气血'], 当前数据.主角.气血);
            _.set(variables, ['stat_data', '主角', '法力值'], 当前数据.主角.法力值);
            return variables;
        }, VARIABLE_OPTION);
    }, { deep: true });
});
